  const dupNames = (list, what) => { const seen = {}; const out = []; list.forEach((x) => { const n = (x.name || '').trim().toLowerCase(); if (!n) return; if (seen[n]) out.push(`Two ${what} are called ${x.name}.`); seen[n] = 1; }); return out; };
