  const FORMULA_IMPL = { min: Math.min, max: Math.max, abs: Math.abs, sqrt: Math.sqrt, round: (v, d) => { const m = Math.pow(10, d || 0); return Math.round(v * m) / m; }, average: (...a) => a.reduce((s, v) => s + v, 0) / (a.length || 1), sum: (...a) => a.reduce((s, v) => s + v, 0), if: (c, a, b) => (c ? a : b), and: (...a) => (a.every(Boolean) ? 1 : 0), or: (...a) => (a.some(Boolean) ? 1 : 0) };
